1	import { useEffect, useState, type CSSProperties } from "react";
2	import { InklingMascot } from "../mascot/InklingMascot";
3	import { prefersReducedMotion } from "../mascot/mascotStore";
4	
5	/** How long each face holds before the next one glides in. */
6	const FACE_HOLD_MS = 3400;
7	
8	/**
9	 * The large, cropped mascot on the first and last welcome screens. It drifts
10	 * and blinks like the sidebar one, and wanders through a few calm faces. It
11	 * owns its own engine, so the library's mascot keeps its clock and its face.
12	 */
13	export function OnboardingMascot({
14	  size,
15	  faces,
16	  style,
17	}: {
18	  size: number;
19	  faces: readonly string[];
20	  style?: CSSProperties;
21	}) {
22	  const [reduced] = useState(prefersReducedMotion);
23	  const [faceIndex, setFaceIndex] = useState(0);
24	
25	  useEffect(() => {
26	    if (reduced || faces.length < 2) return;
27	    const timer = window.setInterval(
28	      () => setFaceIndex((index) => (index + 1) % faces.length),
29	      FACE_HOLD_MS,
30	    );
31	    return () => window.clearInterval(timer);
32	  }, [faces, reduced]);
33	
34	  return (
35	    <div className="first-run-mascot" style={style} aria-hidden="true">
36	      <InklingMascot
37	        size={size}
38	        state="inkling-drift-faced"
39	        expression={faces[faceIndex]}
40	        ink="#2b2623"
41	        paper="#e5ddd2"
42	        playing={!reduced}
43	      />
44	    </div>
45	  );
46	}
