1	import { useEffect, useRef, useState } from "react";
2	import { BotEngine, type BotFrame } from "./bot/engine";
3	import { EXPRESSION_BY_ID, DEFAULT_EXPRESSION } from "./bot/expressions";
4	import { COLOR_BY_ID, SHAPE_BY_ID, DEFAULT_SHAPE } from "./bot/skins";
5	import { RAYON } from "./bot/repere";
6	import { STATE_BY_ID, type StateId } from "./bot/states";
7	import { MascotFigure } from "./MascotFigure";
8	
9	export type { StateId };
10	
11	export interface InklingMascotProps {
12	  size?: number;
13	  shape?: string;
14	  color?: string;
15	  /** Body color as any CSS color, overriding `color` when a skin hex will not do. */
16	  ink?: string;
17	  expression?: string;
18	  paper?: string;
19	  /** Freeze on one exact frame (seconds into the state). No animation loop. */
20	  frozenAt?: number;
21	  state?: StateId;
22	  /** Play the state live (breathing, blinking, gaze drift). Ignored when frozenAt is set. */
23	  playing?: boolean;
24	}
25	
26	/**
27	 * Self-contained mascot: owns its engine and animation loop. Used by the
28	 * dev board (?mascot) and frozen-frame renders. The live app slots share one
29	 * engine through mascotStore instead, so the mascot can move between slots
30	 * without resetting its clock.
31	 */
32	export function InklingMascot({
33	  size = 80,
34	  shape = "inkling-splash",
35	  color = "inkling",
36	  ink: inkOverride,
37	  expression = DEFAULT_EXPRESSION,
38	  paper = "#faf9f6",
39	  frozenAt,
40	  state = "idle",
41	  playing = true,
42	}: InklingMascotProps) {
43	  const shapeRadii = SHAPE_BY_ID.get(shape)?.radii ?? SHAPE_BY_ID.get(DEFAULT_SHAPE)?.radii ?? null;
44	  const ink = inkOverride ?? COLOR_BY_ID.get(color)?.hex ?? "#1a1a1a";
45	  const expr = EXPRESSION_BY_ID.get(expression) ?? null;
46	
47	  const [engine] = useState(() => new BotEngine(RAYON, state, shapeRadii, expr));
48	  const [frame, setFrame] = useState<BotFrame>(() => engine.sample(frozenAt ?? 0));
49	  // Running clock, shared with the transition setters below. Dating a change
50	  // at a stale time (e.g. always 0) completes its morph instantly and reads
51	  // as a hard cut — this ref is what keeps shape/state/expression gliding.
52	  const clockRef = useRef(0);
53	
54	  useEffect(() => {
55	    engine.setShape(shapeRadii, clockRef.current);
56	    engine.setExpression(expr, clockRef.current);
57	    if (frozenAt !== undefined) setFrame(engine.sample(frozenAt));
58	  }, [engine, shapeRadii, expr, frozenAt]);
59	
60	  useEffect(() => {
61	    if (engine.state !== state) engine.setState(state, clockRef.current);
62	    if (frozenAt !== undefined) setFrame(engine.sample(frozenAt));
63	  }, [engine, state, frozenAt]);
64	
65	  useEffect(() => {
66	    if (frozenAt !== undefined || !playing) return;
67	    let raf = 0;
68	    let last = 0;
69	    let clock = 0;
70	    const tick = (ms: number) => {
71	      raf = requestAnimationFrame(tick);
72	      const dt = last ? Math.min((ms - last) / 1000, 0.064) : 0;
73	      last = ms;
74	      clock += dt;
75	      clockRef.current = clock;
76	      setFrame(engine.sample(clock));
77	    };
78	    raf = requestAnimationFrame(tick);
79	    return () => cancelAnimationFrame(raf);
80	  }, [engine, frozenAt, playing]);
81	
82	  return <MascotFigure frame={frame} size={size} ink={ink} paper={paper} />;
83	}
84	
85	export function isKnownMascotState(value: string): value is StateId {
86	  return STATE_BY_ID.has(value as StateId);
87	}
