1	import { clamp, createRng, loopNoise } from "./math";
2	
3	/**
4	 * Les yeux sont peints sur une sphere, pas poses a plat.
5	 *
6	 * Mesure sur la video : l'oeil le plus proche du bord fait 0.69 fois la largeur
7	 * de l'autre, et son aire 0.663 fois — exactement le facteur de profondeur
8	 * (z = 0.669) d'un point de sphere a cette distance du centre. On modelise donc
9	 * une vraie orientation de tete : chaque oeil recupere le repere tangent de la
10	 * sphere, projete en orthographique. La compression et l'inclinaison en
11	 * decoulent toutes seules, c'est ce qui donne le volume.
12	 *
13	 * Les constantes ci-dessous ne sont pas choisies a la main : elles sortent d'un
14	 * ajustement du modele sur les positions et tailles relevees image par image
15	 * (erreur residuelle ~1 px sur un rayon de 190 px).
16	 */
17	
18	type Vec3 = [number, number, number];
19	
20	/** Demi-ecart des yeux sur la sphere, en degres (separation totale ~31deg). */
21	export const EYE_SPLIT = 15.46;
22	/** Taille de l'oeil au repos, en unites de rayon de boule. Design scale x1.2
23	 *  sur l'ajustement mesure (0.186 / 0.412) : lisibilite en petit format. */
24	export const EYE_W = 0.223;
25	export const EYE_H = 0.494;
26	
27	/** Orientation de tete au repos, ajustee sur les frames de reference. */
28	export const REST_GAZE: HeadGaze = { yaw: 28.49, pitch: 28.62, roll: -13 };
29	
30	export interface EyePose {
31	  x: number;
32	  y: number;
33	  /** matrice tangente 2x2 : [a b c d] au sens SVG matrix(a,b,c,d,e,f) */
34	  a: number;
35	  b: number;
36	  c: number;
37	  d: number;
38	  /** composante z de la normale : > 0 = face visible */
39	  depth: number;
40	}
41	
42	export interface HeadGaze {
43	  /** lacet, degres, positif = regarde a droite */
44	  yaw: number;
45	  /** tangage, degres, positif = regarde en haut */
46	  pitch: number;
47	  /** roulis, degres, inclinaison de la tete */
48	  roll: number;
49	}
50	
51	const deg = (d: number) => (d * Math.PI) / 180;
52	
53	/** Fait tourner deux vecteurs d'un repere orthonorme dans leur plan commun. */
54	function spin(u: Vec3, v: Vec3, angle: number): [Vec3, Vec3] {
55	  const c = Math.cos(angle);
56	  const s = Math.sin(angle);
57	  return [
58	    [u[0] * c + v[0] * s, u[1] * c + v[1] * s, u[2] * c + v[2] * s],
59	    [v[0] * c - u[0] * s, v[1] * c - u[1] * s, v[2] * c - u[2] * s],
60	  ];
61	}
62	
63	/**
64	 * Repere de la tete puis des deux yeux.
65	 * Repere ecran : x a droite, y vers le bas, z vers le spectateur.
66	 * L'indice 0 est l'oeil interieur, l'indice 1 l'oeil exterieur.
67	 */
68	export function eyePoses(gaze: HeadGaze, scale: number, split = EYE_SPLIT): [EyePose, EyePose] {
69	  let f: Vec3 = [0, 0, 1];
70	  let right: Vec3 = [1, 0, 0];
71	  let down: Vec3 = [0, 1, 0];
72	
73	  // lacet : forward bascule vers right
74	  [f, right] = spin(f, right, deg(gaze.yaw));
75	  // tangage : forward bascule vers le haut (donc a l'oppose de down)
76	  [down, f] = spin(down, f, deg(gaze.pitch));
77	  // roulis : la tete penche dans son propre plan
78	  [right, down] = spin(right, down, deg(gaze.roll));
79	
80	  const build = (side: number): EyePose => {
81	    const [ef, er] = spin(f, right, deg(split * side));
82	    return {
83	      x: ef[0] * scale,
84	      y: ef[1] * scale,
85	      a: er[0],
86	      b: er[1],
87	      c: down[0],
88	      d: down[1],
89	      depth: ef[2],
90	    };
91	  };
92	
93	  return [build(-1), build(1)];
94	}
95	
96	/**
97	 * Vie au repos : derive lente du regard, saccades, clignements.
98	 *
99	 * Fonction pure du temps (aucun etat interne), donc pause, reprise et saut a
100	 * une date arbitraire donnent toujours la meme image. Les valeurs sont des
101	 * ECARTS a ajouter a la pose de l'etat courant.
102	 */
103	export interface Liveliness {
104	  dYaw: number;
105	  dPitch: number;
106	  dRoll: number;
107	  /** 1 = oeil ouvert, 0 = ferme (ecrasement vertical en repere ecran) */
108	  lid: number;
109	  driftX: number;
110	  driftY: number;
111	  breath: number;
112	}
113	
114	const BLINK_RNG = createRng(0x5eed);
115	/** Calendrier de clignements pre-tire : deterministe et sans etat. */
116	const BLINKS: number[] = (() => {
117	  const out: number[] = [];
118	  let t = 1.4;
119	  while (t < 900) {
120	    out.push(t);
121	    // 1.9 a 4.6 s entre deux clignements, plus un double clignement parfois
122	    t += 1.9 + BLINK_RNG() * 2.7;
123	    if (BLINK_RNG() < 0.18) {
124	      out.push(t);
125	      t += 0.24;
126	    }
127	  }
128	  return out;
129	})();
130	
131	/** Mesure : 1 a 2 frames a 10 fps. */
132	const BLINK_DUR = 0.18;
133	
134	function blinkLid(t: number): number {
135	  for (let i = 0; i < BLINKS.length; i++) {
136	    const start = BLINKS[i]!;
137	    if (t < start) break;
138	    const k = (t - start) / BLINK_DUR;
139	    if (k >= 0 && k <= 1) {
140	      // fermeture rapide, reouverture un peu plus lente
141	      return k < 0.45 ? 1 - k / 0.45 : (k - 0.45) / 0.55;
142	    }
143	  }
144	  return 1;
145	}
146	
147	export interface LivelinessOptions {
148	  wander?: number;
149	  blink?: boolean;
150	  float?: boolean;
151	}
152	
153	export function liveliness(t: number, opt: LivelinessOptions = {}): Liveliness {
154	  const { wander = 1, blink = true, float = true } = opt;
155	
156	  // Periodes premieres entre elles : la derive ne se repete jamais a l'oeil.
157	  return {
158	    dYaw: (loopNoise(t, 11.3, 0.4) * 5.5 + loopNoise(t, 3.7, 2.1) * 1.6) * wander,
159	    dPitch: (loopNoise(t, 9.1, 1.3) * 4.2 + loopNoise(t, 4.3, 0.7) * 1.3) * wander,
160	    dRoll: loopNoise(t, 13.7, 3.2) * 2.2 * wander,
161	    lid: blink ? blinkLid(t) : 1,
162	    // Au repos la video est quasiment immobile (centre stable a +-0.003, rayon
163	    // constant) : toute la vie passe par le regard et les clignements. On garde
164	    // juste de quoi ne pas figer completement l'image.
165	    driftX: float ? loopNoise(t, 7.9, 1.9) * 0.006 : 0,
166	    driftY: float ? loopNoise(t, 5.3, 0.3) * 0.007 : 0,
167	    // La largeur est constante, seule la hauteur respire tres legerement.
168	    breath: float ? 1 + Math.sin((t / 3.4) * Math.PI * 2) * 0.005 : 1,
169	  };
170	}
171	
172	/**
173	 * Le clignement est un ecrasement VERTICAL en repere ecran autour du centre de
174	 * l'oeil (mesure : la largeur de bbox est conservee, la hauteur tombe a ~0.35),
175	 * pas un retrecissement le long de l'axe incline de la gelule. On le compose
176	 * donc apres la matrice tangente, en n'affectant que les sorties en y.
177	 */
178	export function blinkScale(lid: number): number {
179	  return 0.06 + 0.94 * clamp(lid);
180	}
