  for (let i = 0; i < 6; i++) { await snap("s1-" + i); await wait(2000); }
  for (let i = 0; i < 4; i++) { await click("Continue"); await wait(700); }
  await wait(1500);
  for (let i = 0; i < 7; i++) { await snap("s5-" + i); await wait(2000); }
  app.quit();
});
