mkdir -p /tmp/mm && cat > /tmp/mm/main.cjs <<'EOF'
const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const path = require("path");
const out = process.argv[2];
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: 1280, height: 800, show: true, useContentSize: true, webPreferences: { backgroundThrottling: false } });
  await win.loadURL("http://localhost:5173/");
  await wait(2500);
  const snap = async (name) => {
    const img = await win.webContents.capturePage();
    fs.writeFileSync(path.join(out, name + ".png"), img.toPNG());
  };
  const clickText = (sel, t) => win.webContents.executeJavaScript(`(()=>{const b=[...document.querySelectorAll(${JSON.stringify(sel)})].find(x=>x.textContent.trim().includes(${JSON.stringify(t)}));b&&b.click();return !!b})()`);
  await clickText("button", "Settings"); await wait(800);
  await clickText("button", "General"); await wait(800);
  await clickText("button", "Show the welcome again"); await wait(1500);
  for (let i = 0; i < 9; i++) { await snap("s1-" + i); await wait(1700); }
  process.exit(0);
});
EOF
